+  const raw=req.cookies.session
+  if(!raw) return null
+  const verified = await verifyToken(raw)   // returns null on bad signature or expiry
+  if (!verified) return null
+  if (verified.iat + SESSION_TTL_SECONDS < Date.now()/1000) return null
+  const u = await loadUser(verified.sub)
+  return u
