+const BASE_MS = 100;

 export async function withRetry<T>(fn: () => Promise<T>): Promise<T> {
   for (let i = 0; i < MAX_ATTEMPTS; i++) {
     try { return await fn(); }
     catch (e) {
       if (i === MAX_ATTEMPTS - 1) throw e;
